package com.aoo.bcg.common.repair;import com.aoo.bcg.common.config.RoomRuleSnapshot;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class ImmutableConfigSnapshotRepairTest{@Test void correctionAppendsNewVersionAndKeepsHistory(){var old=new RoomRuleSnapshot(1,516,"v1","c1","r1","f1","s1","u1",Instant.EPOCH,Map.of("rounds",8));class Store implements ImmutableConfigSnapshotRepair.AppendOnlyStore{List<ImmutableConfigSnapshotRepair.Supersession>added=new ArrayList<>();public Optional<RoomRuleSnapshot>find(long id){return id==1?Optional.of(old):Optional.empty();}public void append(ImmutableConfigSnapshotRepair.Supersession s){added.add(s);}}var store=new Store();var replacement=new ImmutableConfigSnapshotRepair().publish(store,1,2,"v2",Instant.EPOCH.plusSeconds(1),Map.of("rounds",16),"incorrect rounds");assertEquals(8,old.immutableRules().get("rounds"));assertEquals(16,replacement.immutableRules().get("rounds"));assertEquals(1,store.added.size());assertThrows(IllegalArgumentException.class,()->new ImmutableConfigSnapshotRepair().publish(store,1,1,"v1",Instant.EPOCH,Map.of(),"bad"));}}
